    p=ROOT/'data/processed/mev_full_window';out=ROOT/'reports/mev_expansion';d=json.loads((p/'complete_pool_surplus_distributions.json').read_text());roles={'Operational boundary':[Decimal(0),Decimal(0)],'Actual block fee recipients':[Decimal(0),Decimal(0)],'Other signed address changes':[Decimal(0),Decimal(0)]}
