    (p/'representative_transfer_review.json').write_text(json.dumps(bundle,indent=2,ensure_ascii=False));data=json.dumps(bundle,ensure_ascii=False).replace('</','<\\/');css='body{font-family:-apple-system,"PingFang SC",sans-serif;margin:0;background:#f3f7fb;color:#16324a}main{max-width:1400px;margin:auto;padding:30px}header{background:#102a43;color:white;padding:28px;border-radius:12px}h1{margin:0 0 12px}select,input,button{font:inherit;padding:10px;margin:8px 5px 8px 0;border:1px solid #a6baca;border-radius:6px}select{max-width:100%}table{border-collapse:collapse;width:100%;font-size:13px;background:white}td,th{border:1px solid #d6e2ec;padding:9px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#dcebf4;position:sticky;top:0}td.address{font-family:monospace;font-size:11px;max-width:240px}td.qty{white-space:nowrap}section{margin:22px 0}.scroll{overflow:auto;max-height:75vh}a{color:#086c94}.muted{font-size:13px;line-height:1.8;color:#49647a}.notice{background:#fff1d8;padding:14px;border-radius:8px;line-height:1.8}.toolbar{display:flex;flex-wrap:wrap;align-items:center}button.active{background:#087f87;color:white}'
    js='''const D=DATA;let mode="moves";const pick=document.querySelector("select"),q=document.querySelector("input");D.forEach((c,i)=>pick.add(new Option(c.label,i)));const esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));function addr(a){return a.startsWith("0x")?`<a href="https://etherscan.io/address/${esc(a)}" target="_blank" rel="noreferrer">${esc(a)}</a>`:esc(a)}function render(){const c=D[+pick.value||0];document.querySelector("#meta").innerHTML=`区块 ${c.block} · 纽约时间 ${esc(c.time)}<br>Gas ${c.gas_ETH} ETH · 实际 fee recipient ${addr(c.fee_recipient)}<br><a target="_blank" rel="noreferrer" href="https://etherscan.io/tx/${c.hash}">${c.hash}</a> · <a href="https://etherscan.io/tx/${c.hash}#internal" target="_blank">Internal Txns</a> · <a href="https://etherscan.io/tx/${c.hash}#eventlog" target="_blank">Logs</a>`;let rows=c[mode].filter(r=>JSON.stringify(r).toLowerCase().includes(q.value.toLowerCase()));const keys=mode==="moves"?["event_type","sender","recipient","asset","symbol","quantity","amount_raw","reference"]:["address","asset","symbol","received","sent","net","net_raw"];const titles=mode==="moves"?["事件类型","发送地址","接收地址","资产合约／凭证","币种","数量","原始数量","日志序号／调用路径"]:["地址","资产合约／凭证","币种","收到","付出（含列明的费用）","净变化","原始净变化"];document.querySelector("thead").innerHTML="<tr>"+titles.map(x=>`<th>${esc(x)}</th>`).join("")+"</tr>";document.querySelector("tbody").innerHTML=rows.map(r=>"<tr>"+keys.map(k=>`<td class="${["sender","recipient","address","asset"].includes(k)?"address":""}">${["sender","recipient","address"].includes(k)?addr(r[k]):esc(Array.isArray(r[k])?JSON.stringify(r[k]):r[k])}</td>`).join("")+"</tr>").join("");document.querySelector("#count").textContent=`显示 ${rows.length} 行；收款总额及净变化不自动等于利润。`;document.querySelectorAll("button[data-mode]").forEach(b=>b.classList.toggle("active",b.dataset.mode===mode))}pick.onchange=render;q.oninput=render;document.querySelectorAll("button[data-mode]").forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});render();'''.replace('DATA',data,1)
    page='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>真实收支核对入口</title><style>'+css+'</style><main><header><h1>实际收到多少、转出多少</h1><p>从一笔交易的完整日志和成功内部调用，核对真实原币数量。</p></header><section class="notice">转账数量可直接核实；利润还要扣本金、贷款偿还、区块付款及 Gas。零地址表示 mint/burn 记账；ERC-6909 是余额凭证；NFT 转移的是单位或所有权。它们均不能当作收到原生 ETH。地址关联不自动证明共同控制。</section><div class="toolbar"><select aria-label="选择真实案例"></select><button data-mode="moves">逐条转账与费用</button><button data-mode="net">逐地址收支</button><input placeholder="筛选地址、资产、事件或金额" aria-label="筛选记录"></div><p id="meta" class="muted"></p><p id="count" class="muted"></p><div class="scroll"><table><thead></thead><tbody></tbody></table></div><section><h2>完整分配图</h2><img alt="471个单元的完整资产分配，区分现金与V4凭证" style="max-width:100%" src="complete_transfer_allocation.png"><p><a href="完整套利与MEV核验报告.html">中文报告</a> · <a href="逐笔真实转账与Etherscan链接.csv.gz">完整转账明细 CSV.gz</a> · <a href="逐交易逐地址实际收支.csv.gz">逐地址收支 CSV.gz</a> · <a href="完整池收益逐地址分配.csv">完整池收益分配</a></p><p class="muted">金额来自归档回执／trace，不声称已逐页读取 Etherscan。原始证据位置保存在配套 representative_transfer_review.json 与各明细 CSV；界面不使用浏览器抓取结果代替链上数量。</p></section></main><script>'+js+'</script></html>';(out/'真实收支核对入口.html').write_text(page);print('Allocation figure and transfer review',len(bundle),'cases')
